import java.util.*;
import java.io.*;

public class ar {

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String getNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int getNextInt() {
            return Integer.parseInt(getNext());
        }
    }

    public static void main(String[] args) throws Exception {
        FastReader reader = new FastReader();
        int total = reader.getNextInt();
        int limit = reader.getNextInt();
        int[] data = new int[total];
        for (int i = 0; i < total; i++) data[i] = reader.getNextInt();

        if ((total & 1) == 1) {
            System.out.print(0);
            return;
        }

        Map<Integer, Integer> diffMap = new HashMap<>();
        int evenCount = 0, oddCount = 0;
        for (int i = 0; i < total; i++) {
            if (data[i] % 2 == 0) evenCount++;
            else oddCount++;
            if (evenCount > 0 && oddCount > 0 && evenCount == oddCount && i + 1 < total) {
                diffMap.put(i, Math.abs(data[i] - data[i + 1]));
            }
        }

        if (diffMap.isEmpty()) {
            System.out.print(0);
        } else if (diffMap.size() == 1) {
            int val = new ArrayList<>(diffMap.values()).get(0);
            System.out.print(val <= limit ? 1 : 0);
        } else {
            List<Integer> vals = new ArrayList<>(diffMap.values());
            Collections.sort(vals);
            int count = 0;
            for (int v : vals) {
                if (v <= limit) {
                    limit -= v;
                    count++;
                } else {
                    break;
                }
            }
            System.out.print(count);
        }
    }
}
